def window_admit(events, limit, window):
    def is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not is_int(limit) or limit <= 0:
        raise ValueError("limit must be a positive integer")
    if not is_int(window) or window <= 0:
        raise ValueError("window must be a positive integer")

    if not isinstance(events, (list, tuple)):
        raise ValueError("events must be a list of non-negative integers")

    prev = None
    for t in events:
        if not is_int(t) or t < 0:
            raise ValueError("events must contain non-negative integers")
        if prev is not None and t < prev:
            raise ValueError("events must be non-decreasing")
        prev = t

    accepted = []
    result = []
    for t in events:
        threshold = t - window
        while accepted and accepted[0] <= threshold:
            accepted.pop(0)
        if len(accepted) < limit:
            accepted.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

